select *
from cost_card
where scope_type = #{scopeType}
  and scope_id = #{scopeId}
order by updated_at desc, id desc

select *
from cost_card
where scope_type = #{scopeType}
  and scope_id = #{scopeId}
  and id = #{id}

select count(1)
from cost_card
where scope_type = #{scopeType}
  and scope_id = #{scopeId}
  and card_code like #{prefix}
